import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:s11/shared/data/models/textbook.dart';

// Manuscripts stay local: pass the private fixture generated by the Python
// audit; never commit it or include it in web assets/deployment.
void main() {
  final path = Platform.environment['BOOKDATA_PRIVATE_FIXTURE'];
  test('author corpus survives native BookData round-trip without dropped fields', () {
    final entries = jsonDecode(File(path!).readAsStringSync()) as List;
    expect(entries, isNotEmpty);
    for (final entry in entries) {
      final original = Map<String, dynamic>.from(entry['book'] as Map);
      final decoded = BookData.fromJson(original).toCreateJson();
      void preserved(dynamic before, dynamic after, String location) {
        if (before is Map) {
          expect(after, isA<Map>(), reason: location);
          for (final key in before.keys) {
            // Optional explicit defaults may serialize as an absent key.
            if (!after.containsKey(key) && (before[key] == null ||
                (before[key] is List && before[key].isEmpty) ||
                (key == 'schema_version' && before[key] == 1))) continue;
            expect(after.containsKey(key), isTrue, reason: '$location/$key');
            preserved(before[key], after[key], '$location/$key');
          }
        } else if (before is List) {
          expect(after, isA<List>(), reason: location);
          expect(after.length, before.length, reason: location);
          for (var i = 0; i < before.length; i++) {
            preserved(before[i], after[i], '$location/$i');
          }
        } else {
          expect(after, before, reason: location);
        }
      }
      preserved(original, decoded, entry['path'] as String);
      expect(BookData.fromJson(decoded).toCreateJson(), decoded,
          reason: entry['path'] as String);
    }
  }, skip: path == null ? 'Set BOOKDATA_PRIVATE_FIXTURE for the local author corpus' : false);
}
